def vested(total, months_elapsed, cliff_months=12, term_months=48, cliff_pct=0.25):
    if months_elapsed < cliff_months:
        return 0
    at_cliff = total * cliff_pct
    per_month = (total - at_cliff) / (term_months - cliff_months)
    earned = at_cliff + (months_elapsed - cliff_months) * per_month
    return int(min(earned, total))

for m in (11, 12, 30, 48):
    print(m, "months:", vested(4800, m), "options vested")
